      tagName: el.tagName || '',
      namespaceURI: ns,
      hasChildren: el.children.length > 0,
      // 区分"真渲染文字的叶子" vs "空填色块/分隔条"——后者 toolbar 应该给 fill 控件而不是 text 控件
      hasText: rawText.trim().length > 0,
      singleTextChild: singleTextChild,
      boxW: boxW,
      boxH: boxH,
