      type: 'meta',
      eid: observedEid,
      tagName: meta.tagName,
      namespaceURI: meta.namespaceURI,
      hasChildren: meta.hasChildren,
      hasText: meta.hasText,
      singleTextChild: meta.singleTextChild,
